// server.min.js — servidor MÍNIMO: comprueba que Express arranca y que PostgreSQL responde
// Ejecutar: node --watch --env-file=.env server.min.js
import express from 'express';
import pool from './src/db/conexion.js';

const app = express();

// Ruta de salud: el servidor le pregunta la hora a PostgreSQL
app.get('/api/salud', async (req, res) => {
  const { rows } = await pool.query('SELECT now() AS hora');
  res.json({ ok: true, hora: rows[0].hora });
});

// Antes de escuchar, probamos la conexión: si falla, vemos el error y el servidor no arranca
try {
  await pool.query('SELECT 1');
  console.log('Conexión a PostgreSQL correcta');
} catch (error) {
  console.error('No se pudo conectar a PostgreSQL:', error.message);
  process.exit(1);
}

const PUERTO = process.env.PUERTO ?? 3000;
app.listen(PUERTO, () => console.log(`Servidor en http://localhost:${PUERTO}`));
